        d="M141.758 97.0725L245.61 197.788H198.9L161.067 161.061L160.259 160.282L95.1982 97.1399L194.557 0.0236908H240.324L141.758 97.0725ZM165.404 197.785H97.2129C82.8171 197.819 68.5957 194.605 55.585 188.379C49.611 185.527 43.9379 182.072 38.6523 178.067C33.849 174.418 29.3828 170.336 25.3096 165.872H132.553L165.404 197.785ZM106.334 142.503H9.37012C4.4616 132.486 1.2917 121.692 0 110.591H73.4277L106.334 142.503ZM69.7773 87.219H0.0185547C1.30665 76.1171 4.47577 65.3215 9.3877 55.3059H102.424L69.7773 87.219ZM161.105 0.0227142L128.465 31.9348H25.2881C29.3657 27.4652 33.8399 23.3821 38.6533 19.7356C43.9384 15.7212 49.6114 12.2566 55.5859 9.39478C68.5987 3.17638 82.8193 -0.0328354 97.2139 0.000253291L161.105 0.0227142Z"
